CREATE TABLE IF NOT EXISTS fields (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, heading TEXT NOT NULL, planted TEXT, lat REAL, lng REAL, updated_by TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity (id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT DEFAULT CURRENT_TIMESTAMP, user TEXT, action TEXT, detail TEXT);\nCREATE TABLE IF NOT EXISTS planting_records (id INTEGER PRIMARY KEY AUTOINCREMENT, field_id INTEGER, field_name TEXT NOT NULL, heading TEXT NOT NULL, latitude REAL, longitude REAL, planting_date TEXT NOT NULL, variety TEXT, notes TEXT, created_by TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
